(function(){'use strict';
const C=window.QuidenceGameProjectsContent,E=window.QuidenceGameProjects,host=document.getElementById('game-projects');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lang=()=>window.QuidenceI18n?.locale==='es'?'es':'en',L=x=>typeof x==='string'?x:x?.[lang()]||'',T=(en,es)=>lang()==='es'?es:en;
let active=null,store=null,state=null,notice='',reportOpen=false,lab=[0,1];const stores=new Map();
const step=()=>active.steps[state.step],rec=()=>E.record(state,step().id),now=()=>new Date().toISOString();
const btn=(action,label,extra='')=>`<button type="button" data-action="${action}" ${extra}>${esc(label)}</button>`;
function save(){const result=store.save();status();return result.ok;}
function status(){const el=document.getElementById('gp-status');if(!el)return;el.textContent=store?.problem?T('Browser saving is paused. Your open answers are retained here. Download JSON or copy the report before closing. The earlier stored record has not been replaced.','El guardado está en pausa. Tus respuestas abiertas se conservan aquí. Descarga el JSON o copia el informe antes de cerrar. No se reemplazó el registro anterior.')+' '+({conflict:T('Another tab changed this activity.','Otra pestaña cambió esta actividad.'),unreadable:T('The saved format could not be read.','No se pudo leer el formato guardado.'),full:T('This record reached the storage limit.','El registro alcanzó el límite de almacenamiento.'),unavailable:T('Storage is unavailable or full.','El almacenamiento no está disponible o está lleno.')}[store.problem]||''):notice||T('Drafts save automatically in this browser. Download a copy to keep elsewhere.','Los borradores se guardan automáticamente en este navegador. Descarga una copia para conservarla en otro lugar.');el.classList.toggle('gp-warning',!!store?.problem);}
function open(id){active=C.ACTIVITIES.find(a=>a.id===id);if(!active){active=null;render();return;}if(!stores.has(id)){let storage;try{storage=window.QuidenceStorage||window.localStorage;}catch{storage={getItem(){throw Error('blocked');}};}stores.set(id,E.open(storage,id,crypto.randomUUID()));}store=stores.get(id);state=store.state;if(state.step>=active.steps.length)state.step=0;notice='';reportOpen=false;lab=[0,1];render(true);}
function route(id){const url=new URL(location.href);if(id)url.searchParams.set('activity',id);else url.searchParams.delete('activity');history.pushState(null,'',url);open(id);}
function labels(){return active.labels||[];}
function pair(code){return code==='none'?T('No equilibrium','Ningún equilibrio'):code.split('').map(x=>L(labels()[Number(x)]).split(' · ')[0]).join(' / ');}
function field(f,draft){const value=draft[f.id];const label=`<span>${esc(L(f.label))}</span>`;if(f.type==='ne')return`<fieldset><legend>${esc(L(f.label))}</legend><div class="gp-options">${['00','01','10','11','none'].map(v=>`<label><input type="checkbox" name="${f.id}" value="${v}" ${(value||[]).includes(v)?'checked':''}> ${esc(pair(v))}</label>`).join('')}</div></fieldset>`;if(f.type==='select')return`<label class="gp-field">${label}<select name="${f.id}"><option value="">${T('Choose…','Elige…')}</option>${f.options.map(o=>`<option value="${o.value}" ${value===o.value?'selected':''}>${esc(L(o.label))}</option>`).join('')}</select></label>`;return`<label class="gp-field">${label}<textarea data-speech-explanation name="${f.id}" rows="3" maxlength="12000">${esc(value||'')}</textarea></label>`;}
function matrix(inputs,p){return`<div class="gp-table-scroll"><table class="gp-matrix"><caption>${T('Rows = A; columns = B. Each pair is (A, B).','Filas = A; columnas = B. Cada par es (A, B).')} ${active.id==='food-trucks'?'USD':T('Utility points','Puntos de utilidad')}</caption><thead><tr><th scope="col">A ↓ / B →</th>${labels().map(l=>`<th scope="col">${esc(L(l))}</th>`).join('')}</tr></thead><tbody>${[0,1].map(a=>`<tr><th scope="row">${esc(L(labels()[a]))}</th>${[0,1].map(b=>`<td>${inputs?`<div class="gp-payoffs">${[0,1].map(player=>{const id=`p${a}${b}${player}`;return`<label><span>${player===0?'A':'B'}</span><input name="${id}" inputmode="decimal" type="text" maxlength="24" aria-label="${esc(pair(''+a+b)+' · '+(player===0?'A':'B'))}" value="${esc(rec().draft[id]||'')}"></label>`;}).join('')}</div>`:`(${p[a][b].map(n=>new Intl.NumberFormat(lang()).format(n)).join(' ; ')})`}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function support(type){rec().support.push({type,at:now(),locale:lang()});save();}
function checksHtml(r){const last=r.submissions.at(-1);if(!last)return'';const changed=JSON.stringify(r.draft)!==JSON.stringify(last.answers);return`<section class="gp-feedback"><h3>${T('Your saved attempt','Tu intento guardado')}</h3><p>${changed?T('You have a newer draft. Submit it to create another version.','Tienes un borrador más reciente. Envíalo para crear otra versión.'):T('This version is saved. You may revise it; earlier submissions remain in your history.','Esta versión está guardada. Puedes revisarla; los envíos anteriores quedan en el historial.')}</p>${last.checks.length?`<ul>${last.checks.map(c=>`<li>${esc(checkName(c.id))}: ${c.status==='matched'?T('matches the model','coincide con el modelo'):c.status==='recheck'?T('compare again','compara de nuevo'):T('not answered / uncertain','sin respuesta / duda')}</li>`).join('')}</ul>`:''}<p>${T('Explanations and recommendations remain open for self or teacher review. No mastery or effort score is assigned.','Las explicaciones y recomendaciones quedan abiertas a revisión propia o docente. No se asignan puntuaciones de dominio ni esfuerzo.')}</p></section>`;}
function checkName(id){if(id.startsWith('p'))return pair(id.slice(1,3))+' · '+(id[3]==='0'?'A':'B');return L(step().fields.find(f=>f.id===id)?.label)||id;}
function reference(){const s=step();if(s.model){const p=E.model(s.model),a=E.analysis(p);return matrix(false,p)+`<p>${T('Pure Nash equilibria','Equilibrios de Nash puros')}: ${a.ne.map(pair).join(', ')}. ${T('Strictly dominant choice for both','Opción estrictamente dominante para ambos')}: ${a.dominance==='none'?T('neither','ninguna'):esc(L(labels()[+a.dominance]))}.</p><p>${T('A best response holds the other choice fixed and maximizes your own payoff. At an equilibrium neither player has a strictly profitable unilateral deviation. Ties count as best responses.','Una mejor respuesta mantiene fija la elección ajena y maximiza el pago propio. En un equilibrio nadie tiene una desviación unilateral estrictamente rentable. Los empates cuentan como mejores respuestas.')}</p>${s.model==='trucks50'?`<p>${T('NN gives total truck profit 400; split locations give 650. Yet the south truck can improve from 150 to 200 by moving north. A higher total is not sufficient for equilibrium.','NN da una ganancia total de 400; separados dan 650. Pero el puesto sur mejora de 150 a 200 si va al norte. Un total mayor no basta para un equilibrio.')}</p>`:''}${s.model==='trucks60'?`<p>${T('At NN, moving south ties at 200. N is weakly, but not strictly, dominant. NN, NS and SN all qualify.','En NN, moverse al sur empata en 200. N domina débilmente, pero no estrictamente. NN, NS y SN son equilibrios.')}</p>`:''}${explorer(p)}`;}return`<p>${esc(L(s.solution)||T('Compare your stated assumptions, the other person’s incentives, evidence for any revision, and whether the action can actually be carried out. More than one recommendation can be defensible.','Compara tus supuestos, los incentivos de la otra persona, las pruebas que motivan revisiones y si la acción puede realizarse. Más de una recomendación puede ser defendible.'))}</p>`;}
function explorer(p){const [a,b]=lab,truck=active.id==='food-trucks',south=step().model==='trucks50'?50:step().model==='trucks60'?60:80;const benefit=a===0&&b===0?10:a===1&&b===1?3:6,cost=step().model==='printerTraining'?2:5,fee=step().model==='printer15'?1.5:step().model==='printer3'?3:0;return`<div class="gp-explorer"><h3>${T('Explore one change at a time','Explora un cambio a la vez')}</h3><p>${T('The story is simultaneous. These controls analyze hypothetical choices; they do not turn it into a turn-taking game.','La historia es simultánea. Los controles analizan elecciones hipotéticas; no convierten el juego en uno por turnos.')}</p><div class="gp-zones">${labels().map((label,i)=>`<div><strong>${esc(L(label))}</strong><p>${truck?(i===0?'120':south)+' '+T('customers','clientes'):T('Separate checklists for A and B','Listas distintas para A y B')}</p><span>${a===i?'A ':''}${b===i?'B':''}</span></div>`).join('')}</div><div class="gp-actions">${[0,1].map(player=>`<label>${player===0?'A':'B'}<select data-lab="${player}">${labels().map((l,i)=>`<option value="${i}" ${lab[player]===i?'selected':''}>${esc(L(l))}</option>`).join('')}</select></label>`).join('')}</div><p>${[a,b].map((v,i)=>{const n=truck?(v===0?120:south)/(a===b?2:1):benefit;return(i===0?'A':'B')+': '+(truck?`${n} × 5 − 100`: `${n} − ${v===0?cost:0} − ${v===1?fee:0}`)+' = '+p[a][b][i];}).join(' · ')}</p><p>${T('Only A switches','Solo cambia A')}: ${p[a][b][0]} → ${p[1-a][b][0]}. ${T('Only B switches','Solo cambia B')}: ${p[a][b][1]} → ${p[a][1-b][1]}.</p></div>`;}
function context(){const s=step();return{activity:C.VERSION,title:L(active.title),story:L(active.story),stepId:s.id,prompt:L(s.body),fields:s.fields.map(f=>({id:f.id,label:L(f.label),options:f.options?.map(o=>({value:o.value,label:L(o.label)}))})),model:s.model||null,modelPayoffs:s.model?E.model(s.model):null,branch:s.branches?L(s.branches[rec().draft.branch]):null};}
function markdown(){let out='# '+L(active.title)+'\n\n'+L(active.story)+'\n\n'+T('Original answers, revisions and support. Explanations require human review.','Respuestas originales, revisiones y apoyos. Las explicaciones requieren revisión humana.')+'\n\n';const quote=x=>String(x).split('\n').map(line=>'> '+line).join('\n');for(const s of active.steps){const r=E.record(state,s.id);out+='## '+L(s.title)+'\n\n'+L(s.body)+'\n\n';for(const [i,v]of r.submissions.entries()){out+='### '+T('Submission','Envío')+' '+(i+1)+' · '+v.at+'\n\n'+v.context.prompt+'\n\n'+(v.context.branch||'')+'\n\n';for(const [key,val]of Object.entries(v.answers))out+=(v.context.fields.find(f=>f.id===key)?.label||key)+'\n\n'+quote(Array.isArray(val)?val.join(', '):val)+'\n\n';out+=T('Objective checks','Comprobaciones objetivas')+': '+v.checks.map(x=>x.id+'='+x.status).join(', ')+'\n\n';out+=T('Support at submission','Apoyo al enviar')+': '+JSON.stringify(v.support)+'\n\n';}out+='### '+T('Current draft (may be unsubmitted)','Borrador actual (puede estar sin enviar)')+'\n\n';for(const [key,val]of Object.entries(r.draft))out+=key+'\n\n'+quote(Array.isArray(val)?val.join(', '):val)+'\n\n';out+=T('Viewed hints and references','Pistas y referencias consultadas')+': '+JSON.stringify(r.support)+'\n\n';}return out;}
function payload(){const result={schema:'quidence_game_project_report_v1',kind:'game-theory-project',check:L(active.title),contentVersion:C.VERSION,activity:active.id,exportedAt:now(),state:E.clone(state),definition:E.clone(active),reportText:markdown()};try{return window.QuidenceReportStore.prepare('ac01',result,'project:'+active.id+':'+state.sessionId);}catch{return result;}}
function report(){return`<section class="gp-card gp-report"><h2>${T('Your complete record','Tu registro completo')}</h2><p>${T('The JSON includes exact original answers, all submissions, prompt and condition snapshots, help viewed and current drafts. Markdown is readable. Nothing here automatically grades your explanations.','El JSON incluye respuestas originales exactas, todos los envíos, copias de preguntas y condiciones, ayudas consultadas y borradores actuales. Markdown es legible. No se califican automáticamente tus explicaciones.')}</p><div class="gp-actions">${btn('json',T('Download JSON','Descargar JSON'))}${btn('md',T('Download Markdown','Descargar Markdown'))}${btn('copy',T('Copy report','Copiar informe'))}${btn('archive',T('Save to My reports','Guardar en Mis informes'))}</div><label class="gp-field">${T('Manual copy fallback: select and copy this text','Copia manual alternativa: selecciona y copia este texto')}<textarea id="gp-copy" rows="10" readonly>${esc(markdown())}</textarea></label></section>`;}
function render(focus=false){host.lang=lang();if(!active){host.innerHTML=`<section class="gp-hero"><p class="gp-eyebrow">${T('GAME THEORY · PROJECTS & CASES','TEORÍA DE JUEGOS · PROYECTOS Y CASOS')}</p><h1>${T('Small decisions.<br>Shared consequences.','Decisiones pequeñas.<br>Consecuencias compartidas.')}</h1><p>${T('Use payoff models when the assumptions are clear. Use evidence and conditional plans when they are not.','Usa modelos de pagos cuando los supuestos estén claros. Usa pruebas y planes condicionales cuando no lo estén.')}</p></section><div class="gp-hub">${C.ACTIVITIES.map((a,i)=>`<article class="gp-card"><div class="gp-cover" aria-hidden="true"><span>${['N ↔ S','C + D','? → !'][i]}</span><i>${['A','A','Kai'][i]}</i><i>${['B','B',T('Team','Equipo')][i]}</i></div><p class="gp-eyebrow">${esc(L(a.kind))}</p><h2>${esc(L(a.title))}</h2><p>${esc(L(a.intro))}</p>${btn('open',T('Open activity →','Abrir actividad →'),`data-id="${a.id}"`)}</article>`).join('')}</div><p>${T('Try the four foundation lessons first if payoff tables and best responses are new to you. Each activity keeps a separate draft. Records stay in this browser; export before clearing site data.','Prueba primero las cuatro lecciones si las tablas de pagos y mejores respuestas son nuevas para ti. Cada actividad conserva un borrador independiente. Los registros quedan en este navegador; expórtalos antes de borrar los datos.')}</p>`;return;}
 const s=step(),r=rec(),submitted=r.submissions.length>0,referenceSeen=r.support.some(x=>x.type==='reference');
 host.innerHTML=`<div class="gp-actions">${btn('hub',T('← All projects & cases','← Todos los proyectos y casos'))}${btn('report',T('Review / export record','Revisar / exportar registro'))}</div><p id="gp-status" role="status"></p>${store.problem&&store.original!==null?btn('raw',T('Download preserved earlier record','Descargar registro anterior conservado')):''}<header class="gp-heading"><p class="gp-eyebrow">${esc(L(active.kind))}</p><h1 tabindex="-1">${esc(L(active.title))}</h1></header><nav class="gp-steps" aria-label="${T('Activity steps','Pasos de la actividad')}">${active.steps.map((s,i)=>btn('step',String(i+1)+(state.records[s.id]?.submissions.length?' ✓':''),`data-index="${i}" aria-label="${esc(L(s.title))}" ${i===state.step?'aria-current="step"':''} ${i>0&&!state.records[active.steps[i-1].id]?.submissions.length&&i>state.step?'disabled':''}`)).join('')}</nav><details class="gp-card gp-story" ${state.step===0?'open':''}><summary>${T('Situation & fixed assumptions','Situación y supuestos fijos')}</summary><p>${esc(L(active.story))}</p>${active.id==='missed-deadline'?`<ol class="gp-timeline"><li>${T('Wed 16:30 · “I’ll work on it later”','Mié 16:30 · «Lo haré después»')}</li><li>${T('Wed 17:00 · First graph promised','Mié 17:00 · Primera gráfica prometida')}</li><li>${T('Wed 18:00 · Your initial decision','Mié 18:00 · Tu decisión inicial')}</li><li>${T('Fri 15:00 · Poster due','Vie 15:00 · Entrega del cartel')}</li></ol>`:''}</details><section class="gp-card"><h2>${esc(L(s.title))}</h2><p>${esc(L(s.body))}</p><form id="gp-form">${s.matrix?`<p>${T('Use a dot or comma for decimals (1.5 or 1,5); do not use thousands separators.','Usa punto o coma decimal (1.5 o 1,5); no uses separadores de miles.')}</p>`+matrix(true):''}${s.fields.map(f=>field(f,r.draft)+(f.id==='branch'?`<p class="gp-branch" id="gp-branch">${esc(L(s.branches[r.draft.branch]))}</p>`:'')).join('')}<label class="gp-check"><input type="checkbox" name="unsure" ${r.draft.unsure?'checked':''}>${T('I am unsure; keep this uncertainty in my record.','Tengo dudas; conserva esta incertidumbre en mi registro.')}</label><label class="gp-check"><input type="checkbox" name="otherHelp" ${r.draft.otherHelp?'checked':''}>${T('I used other help on this step.','Usé otra ayuda en este paso.')}</label><div class="gp-actions"><button class="primary" type="submit">${T(submitted?'Save revision':'Submit my response',submitted?'Guardar revisión':'Enviar mi respuesta')}</button>${btn('next',state.step===active.steps.length-1?T('Review record →','Revisar registro →'):T('Next step →','Siguiente paso →'),submitted&&JSON.stringify(r.draft)===JSON.stringify(r.submissions.at(-1).answers)?'':'disabled')}</div><p id="gp-answer-status" role="status"></p></form>${checksHtml(r)}<div class="gp-actions">${state.step>0?btn('hint',r.support.some(x=>x.type==='hint')?T('Open a second hint','Abrir una segunda pista'):T('Open a hint','Abrir una pista'),r.support.some(x=>x.type==='hint2')?'disabled':''):''}${submitted?btn('reference',T('Open reference discussion','Abrir análisis de referencia')):''}</div><div class="gp-support">${r.support.some(x=>x.type==='hint')?`<p>${esc(L(s.hint)||T('Name what you know, what you assume, and what new evidence would change your plan. Compare only outcomes allowed by the stated rules.','Nombra lo que sabes, lo que supones y qué pruebas cambiarían tu plan. Compara solo resultados permitidos por las reglas.'))}</p>`:''}${r.support.some(x=>x.type==='hint2')?'<p>'+esc(active.id==='food-trucks'?T('Same location means split customers. Deduct the fixed cost once per truck. Test a switch by comparing one truck’s own profits, not the total.','La misma zona implica dividir clientes. Resta el costo fijo una vez por puesto. Prueba un cambio comparando la ganancia propia, no el total.'):active.id==='shared-printer'?T('A deduction affects only the club that skips; nobody receives it. Recheck DD as well as CC, especially with a 1.5-point deduction.','La deducción afecta solo al club que omite; nadie la recibe. Revisa DD además de CC, especialmente con una deducción de 1,5.'):T('A skill obstacle, an incentive to wait and an unknown reason call for different evidence. Specify what you will check, when, and what you can credibly do if it fails.','Un obstáculo de conocimientos, un incentivo a esperar y un motivo desconocido requieren pruebas distintas. Especifica qué revisarás, cuándo y qué puedes hacer de forma creíble si falla.'))+'</p>':''}${referenceSeen?reference():''}</div></section>${reportOpen?report():''}`;
 status();if(focus)host.querySelector('h1')?.focus();
}
function collect(){const form=host.querySelector('#gp-form');if(!form)return;const draft={};for(const el of form.elements){if(!el.name)continue;if(el.type==='checkbox'){if(el.name==='ne'){draft.ne=draft.ne||[];if(el.checked)draft.ne.push(el.value);}else draft[el.name]=el.checked;}else draft[el.name]=el.value;}rec().draft=draft;notice='';save();const next=host.querySelector('[data-action="next"]');if(next)next.disabled=!rec().submissions.length||JSON.stringify(rec().submissions.at(-1).answers)!==JSON.stringify(draft);}
host.addEventListener('input',e=>{if(e.target.closest('#gp-form')){if(e.target.name==='ne'&&e.target.checked)host.querySelectorAll('[name="ne"]').forEach(x=>{if(x!==e.target&&(e.target.value==='none'||x.value==='none'))x.checked=false;});collect();}});
host.addEventListener('change',e=>{if(e.target.hasAttribute('data-lab')){lab[+e.target.dataset.lab]=+e.target.value;const target=e.target.dataset.lab;render();host.querySelector('[data-lab="'+target+'"]').focus();}else if(e.target.name==='branch'){collect();host.querySelector('#gp-branch').textContent=L(step().branches[e.target.value]);}});
host.addEventListener('submit',e=>{if(e.target.id!=='gp-form')return;e.preventDefault();collect();const r=rec(),s=step();const hasAnswer=Object.entries(r.draft).some(([k,v])=>!['otherHelp','unsure'].includes(k)&&(typeof v==='string'?v.trim():Array.isArray(v)&&v.length));if(!hasAnswer&&!r.draft.unsure){host.querySelector('#gp-answer-status').textContent=T('Add a response or mark that you are unsure.','Agrega una respuesta o indica que tienes dudas.');return;}if(s.branches&&!r.draft.branch){host.querySelector('#gp-answer-status').textContent=T('Choose branch B or C so its conditions are saved with your response.','Elige la rama B o C para guardar sus condiciones junto a tu respuesta.');return;}const checks=E.check(s,r.draft);r.submissions.push({at:now(),locale:lang(),answers:E.clone(r.draft),context:context(),support:E.clone(r.support),checks});notice=T('Response recorded. Earlier versions are preserved.','Respuesta registrada. Se conservan las versiones anteriores.');save();render();host.querySelector('[data-action="next"]').focus();});
function download(content,name,type){try{const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);notice=T('Download requested. Check your downloads.','Descarga solicitada. Revisa tus descargas.');status();}catch{reportOpen=true;notice=T('Download unavailable. Select and copy the report below.','Descarga no disponible. Selecciona y copia el informe de abajo.');render();}}
host.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='open'){route(b.dataset.id);return;}if(a==='hub'){route(null);return;}if(!active)return;
 if(a==='step'||a==='next'){if(a==='next'&&state.step===active.steps.length-1){reportOpen=true;render();host.querySelector('.gp-report').scrollIntoView();return;}state.step=a==='step'?+b.dataset.index:state.step+1;reportOpen=false;lab=[0,1];notice='';save();render(true);}
 else if(a==='hint'){support(rec().support.some(x=>x.type==='hint')?'hint2':'hint');render();}
 else if(a==='reference'){if(!rec().submissions.length)return;support('reference');render();}
 else if(a==='report'){reportOpen=!reportOpen;render();if(reportOpen)host.querySelector('.gp-report').scrollIntoView();}
 else if(a==='json')download(JSON.stringify(payload(),null,2),'Quidence_'+active.id+'.json','application/json');
 else if(a==='md')download(markdown(),'Quidence_'+active.id+'.md','text/markdown;charset=utf-8');
 else if(a==='raw')download(store.original,'Quidence_'+active.id+'_preserved.json','application/json');
 else if(a==='copy'){const area=host.querySelector('#gp-copy');try{await navigator.clipboard.writeText(area.value);notice=T('Report copied.','Informe copiado.');}catch{area.focus();area.select();notice=T('Text selected. Use your device’s Copy command.','Texto seleccionado. Usa el comando Copiar de tu dispositivo.');}status();}
 else if(a==='archive'){const result=window.QuidenceReportStore.save('ac01',payload(),'project:'+active.id+':'+state.sessionId);notice=result.ok?T('A copy is now in Saved reports.','Ya hay una copia en Informes guardados.'):T('The report could not be archived. Download or copy it here.','No se pudo archivar el informe. Descárgalo o cópialo aquí.');status();}
});
document.addEventListener('quidence:language',()=>{notice='';render();});window.addEventListener('popstate',()=>open(new URL(location.href).searchParams.get('activity')));window.addEventListener('storage',()=>{if(store&&store.changed()){store.save();status();}});window.addEventListener('beforeunload',e=>{if([...stores.values()].some(s=>s.problem)){e.preventDefault();e.returnValue='';}});
open(new URL(location.href).searchParams.get('activity'));
})();
